def getUnfulfilledCustomers(requests, totalInventory):
    req = sorted(requests, key=lambda r: (-r[2], r[3]))
    inv, i, n = totalInventory, 0, len(req)
    unfulfilled = []
    while i < n:
        j = i
        while j < n and req[j][2] == req[i][2]:
            j += 1
        group = req[i:j]
        need = sum(r[1] for r in group)
        if inv >= need:
            inv -= need
        else:
            unfulfilled += [r[0] for r in group[inv:]]  # first `inv` customers get 1 unit in round one
            inv = 0
        i = j
    return sorted(unfulfilled)
